"""Owner UI, never sends an invitation or reveals a stored code."""

def page(rows=(), active=False):
    import html
    history=''.join('<li>'+html.escape(str(r['label'] or 'ללא כינוי'))+' · '+html.escape(str(r['id']))+' · '+('בוטל' if r['revoked_at'] else 'מומש' if r['redeemed_at'] else 'ממתין למימוש')+'</li>' for r in rows)
    rendered = '''<!doctype html><html lang="he" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>הזמנות למפות | Change Navigator</title><style>body{font-family:Arial;background:#eef4f8;color:#0d2340;margin:0;padding:28px}main{max-width:1000px;margin:auto}h1{font-size:32px}.layout{display:grid;grid-template-columns:1fr 290px;gap:24px}.card{background:white;padding:24px;border-radius:18px;border:1px solid #d7e3ed;margin-bottom:20px}label{display:block;margin:16px 0 8px}input,button{font:inherit;padding:12px;border:1px solid #aabccd;border-radius:9px;box-sizing:border-box}input:not([type=checkbox]){width:100%}button{background:#0d2340;color:white;cursor:pointer;margin-top:14px}button:disabled{opacity:.5;cursor:not-allowed}.note{background:#e0f2fe;padding:16px;border-radius:12px;line-height:1.7}p,li{line-height:1.7}.code{overflow-wrap:anywhere;direction:ltr;text-align:left;font-family:monospace;font-size:20px;background:#eef4f8;padding:12px}img{max-width:230px;width:100%}a{color:#075985}#output:empty{display:none}@media(max-width:700px){body{padding:18px}.layout{grid-template-columns:1fr}h1{font-size:26px}}</style><main><a href="/admin">חזרה לניהול</a><h1>הזמנות למפות</h1><p>Change Navigator | עדי בן נשר</p><div class="note">הכנה לבדיקה בלבד. יש להשלים מיגרציה, חיבור מאובטח של כתובת MAPS ואישור הפעלה לפני מתן גישה למוזמנים. לא נשלחות הודעות אוטומטית.</div><div class="layout"><section><div class="card"><h2>קוד למכשיר אחד</h2><form id="issue"><label for="label">כינוי פנימי להזמנה, ללא פרטי מתאמנים</label><input id="label" maxlength="120"><label for="expiry">תוקף למימוש הקוד, לפי בחירתך</label><input id="expiry" type="datetime-local" required><label><input id="eligible" type="checkbox" required> אישרתי שהמוזמן הוא מאמן זכיין תות ושמסירת החומרים תואמת לאישורי בעלי התוכן.</label><p>מימוש ראשון יקשר את הקוד להתקנת הדפדפן הזו. דפדפן אחר, מחשב נוסף או ניקוי נתונים מחייבים קוד חדש. זו אינה מניעת העתקה טכנית.</p><button id="issue-button" disabled>הנפקת קוד, ללא שליחה</button></form><p id="status" role="status"></p><div id="output"></div></div><div class="card"><h2>ביטול גישה עתידית</h2><form id="revoke"><label for="invite-id">מזהה ההזמנה</label><input id="invite-id" required><button>ביטול ההזמנה והעדכונים המקוונים</button></form><p>ביטול אינו מוחק מפות שכבר הורדו למכשיר. העותק המקומי יכול להמשיך לפעול בלי אינטרנט.</p></div></section><aside class="card"><h2>QR לכניסה מהנייד</h2><img src="/static/maps-entry-qr.png" alt="קוד QR לכתובת MAPS המתוכננת"><p><b>כתובת מתוכננת, טרם הופעלה</b><br><span dir="ltr">maps.changenavigator.co.il</span></p><p>ה-QR מכיל כתובת בלבד, לא קוד אישי. את הקוד מוסרים בנפרד למוזמן המאושר.</p><p>במחשב: לאחר אימות הקוד, כפתור התקנה יופיע בדפדפן תומך. באייפון מוצגות הוראות הוספה למסך הבית.</p></aside></div></main><script>
const form=document.getElementById('issue'),button=document.getElementById('issue-button');form.oninput=()=>button.disabled=!form.checkValidity();
form.onsubmit=async e=>{e.preventDefault();button.disabled=true;const status=document.getElementById('status'),out=document.getElementById('output');out.replaceChildren();try{const r=await fetch('/admin/maps-invitations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({label:document.getElementById('label').value,expires_at:new Date(document.getElementById('expiry').value).toISOString(),eligible_tut_franchisee:document.getElementById('eligible').checked})});if(!r.ok)throw Error();const x=await r.json();const p=document.createElement('p');p.textContent='שמרו את הקוד כעת. מוצג פעם אחת בלבד, ולא נשלח לאף אחד.';const code=document.createElement('div');code.className='code';code.textContent=x.code;const id=document.createElement('p');id.textContent='מזהה לביטול: '+x.id;out.append(p,code,id);document.getElementById('invite-id').value=x.id;status.textContent='הקוד נוצר. לא נשלחה הודעה.';}catch(e){status.textContent='הקוד לא הונפק. בדקו שההפעלה והמיגרציה אושרו והושלמו.';}button.disabled=!form.checkValidity();};
document.getElementById('revoke').onsubmit=async e=>{e.preventDefault();if(!confirm('לבטל את הגישה המקוונת? עותק שכבר הורד לא יימחק.'))return;const r=await fetch('/admin/maps-invitations/'+encodeURIComponent(document.getElementById('invite-id').value)+'/revoke',{method:'POST'});document.getElementById('status').textContent=r.ok?'הגישה המקוונת בוטלה.':'לא ניתן לבטל כעת.';};
</script></html>'''
    rendered=rendered.replace('</main>', '<section class="card"><h2>הזמנות אחרונות</h2><ul>'+history+'</ul><p>מוצגות עד 100 הזמנות. קודים אינם נשמרים בצורה שניתן להציג שוב.</p></section></main>')
    if active:
        rendered=rendered.replace('הכנה לבדיקה בלבד. יש להשלים מיגרציה, חיבור מאובטח של כתובת MAPS ואישור הפעלה לפני מתן גישה למוזמנים. לא נשלחות הודעות אוטומטית.', 'ההנפקה הופעלה. יש לוודא שכתובת MAPS פועלת ושמקבל ההזמנה זכאי לקבלת החומרים. לא נשלחות הודעות אוטומטית.')
    return rendered
